    long highBits = NumericUtils.doubleToSortableLong(high);
    baseValue = NumericUtils.sortableLongToDouble(TestUtil.nextLong(random(), lowBits, highBits));
  } else if (surpriseMe == 1) {
    // edge case
    baseValue = low;
  } else if (surpriseMe == 2) {
    // edge case
